import pathlib
root=pathlib.Path(__file__).resolve().parents[1]
page=(root/'docs/protein.html').read_text(encoding='utf-8')
page=page.replace('data-category="protein"','data-category="creatine"').replace('Protein | Supplement Research','Creatine | Supplement Research')
page=page.replace('Compare protein powders available in India by price, protein content, nutrition, flavour and pack size.','Compare creatine powders in India by chemical form, processing, flavour, pack price and cost per gram of labelled compound.')
page=page.replace('<a href="protein.html" aria-current="page">Protein</a><a href="creatine.html">Creatine</a>','<a href="protein.html">Protein</a><a href="creatine.html" aria-current="page">Creatine</a>')
page=page.replace('data/catalog.json','data/creatine.json').replace('THE INDIA PROTEIN CATALOG','THE INDIA CREATINE CATALOG').replace('Find your protein.','Compare your creatine.').replace('Know what you pay.','Every form. Every gram.')
page=page.replace('Compare real pack prices and the cost of actual protein. Explore whey, plant, yeast and more, with nutrition and sources in one place.','Explore monohydrate, HCl and nitrate. Compare actual pack prices, processing labels and disclosed creatine quantities, with official sources for each offer.')
page=page.replace('All nutrition fields available</label>','All nutrition fields available</label><label class="check"><input type="checkbox" name="knownCost">Compound cost available</label>')
page=page.replace('Filters apply together to individual pack offers. Blank nutrition is unknown, never zero.','Filters apply together to individual pack offers. Unknown values stay blank. Micronized is a processing label; Creapure is an ingredient trademark.')
page=page.replace('Lowest cost / g protein','Lowest cost / g compound').replace('<option value="protein">Highest protein %</option>','<option value="powderCost">Lowest cost / g powder</option><option value="creatine">Highest compound %</option><option value="doseCost">Lowest cost / 3 g compound</option>')
page=page.replace('<div class="table-wrap">','<p class="catalog-note">Cost / g compound uses the labelled monohydrate, HCl or nitrate mass—not free-creatine equivalents. These prices do not establish equal efficacy. “Iso”, “concentrated” and “normal” are not assigned without a clear brand definition. <a href="data/India_Creatine_Catalog.xlsx" download>Download Excel ↗</a></p><div class="table-wrap">')
page=page.replace('<th>Type / subclass</th>','<th>Form / processing</th>').replace('<th>₹ / g protein</th><th>Protein</th>','<th>₹ / g powder</th><th>₹ / g compound</th><th>Compound</th>')
page=page.replace('<strong>Actual protein, actual cost.</strong> Cost per gram = pack price ÷ (pack grams × protein percentage ÷ 100). Rounded for display; sorting uses full precision.','<strong>Two cost measures.</strong> Powder cost = price ÷ pack grams. Compound cost = price ÷ (pack grams × labelled compound percentage ÷ 100). Unknown concentration means no compound cost. A 3 g comparison quantity is available in Details and filters; it is not dosage advice.')
page=page.replace('<strong>Exact sizes only.</strong> Single 1 kg, 2 kg and 4 kg packs. No extrapolated prices or multipack comparisons. Sold-out offers remain visible and can be filtered out.','<strong>Actual packs only.</strong> All verified single-pack weights are included, including small jars and pouches. No extrapolated 1 kg, 2 kg or 4 kg prices. Bundles, multipacks, free gifts, tablets and gummies are excluded. Sold-out offers are labelled.')
page=page.replace('<strong>Evidence has limits.</strong> Selected prominent brands, not a market-share ranking. Some protein values are indicative product-family claims. Nutrition notes disclose conflicts, serving proxies and shared labels. No inference of missing calories or scoop size.','<strong>Forms and evidence.</strong> Monohydrate, hydrochloride and nitrate are chemical forms. Micronization describes processing. Creapure and Creasure are trademarks. Product-family claims are identified; flavour-specific quantities are not inferred from an unflavoured label. Coverage is a researched selection, not every creatine product sold in India.')
page=page.replace('Protein Index / India','Supplement Research / India')
(root/'docs/creatine.html').write_text(page,encoding='utf-8')
